<script setup lang="ts">
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import {createInstallPreview,installStep,installTitle,installSteps,installPhases,type InstallAuthorization} from '../utils/install-wizard'
import {createLiveInstall,type InstallState} from '../utils/install-live'

definePageMeta({layout:false,colorMode:'light'})
const route=useRoute(),router=useRouter(),config=useRuntimeConfig(),preview=import.meta.dev&&route.query.preview==='1'
const requestFetch=useRequestFetch()
const initial=preview?null:(await requestFetch<{data:InstallState}>('/api/v1/install/state')).data
if(initial?.complete)await navigateTo('/admin/login',{replace:true})
const live=initial?createLiveInstall(initial,async(path,options)=>{const result=await $fetch<{data:any}>('/api/v1/install'+path,{...options,body:options.body as Record<string,unknown>|undefined,timeout:30000});return result.data}):null
const wizard=live??createInstallPreview(installStep(route.query.step),undefined,async signal=>{
 const response=await $fetch<{data:InstallAuthorization}>(String(config.public.apiBase)+'/install/authorization',{signal,timeout:8000})
 return response.data
})
const {step,accepted,errors,notice,environment,connections,checkingEnvironment,checkingConnections,installing,environmentResult,connectionResult,installationResult,phases,installationError,form,locked,progress}=wizard
const {authorization,checkingAuthorization,authorizationScenario,authorizationView,authorizationAllowed}=wizard
const authorizationOptions=[{label:'当前本机授权',value:'live'},{label:'已授权（演示）',value:'active'},{label:'未授权（演示）',value:'unlicensed'},{label:'授权到期（演示）',value:'expired'},{label:'授权停用（演示）',value:'suspended'},{label:'验签失败（演示）',value:'verification_failed'},{label:'域名不匹配（演示）',value:'domain_mismatch'},{label:'连接失败（演示）',value:'unavailable'}]
const authenticated=live?.authenticated??ref(true),accessBusy=live?.accessBusy??ref(false),accessError=live?.accessError??ref('')
const redis=wizard.redis,installHelpOpen=ref(false),redisExpanded=ref(false),pageMounted=ref(false),environmentAutoStarted=ref(false)
const passwordVisible=reactive({redis:false,database:false,administrator:false,confirmation:false})
const environmentChecks=live?.environmentChecks??ref([]),environmentError=live?.environmentError??ref(''),connectionError=live?.connectionError??ref(''),recoveryRequired=live?.recoveryRequired??ref(false)
const {canResume,resuming}=wizard
if(!preview&&initial?.authenticated&&!initial.complete&&String(route.query.step||'')!==String(step.value+1))await navigateTo({path:'/install',query:{step:String(step.value+1)}},{replace:true})
const current=computed(()=>installSteps[step.value]!)
useHead(()=>({title:installTitle(String(step.value+1))}))
const results=[{label:'成功效果',value:'success'},{label:'失败效果',value:'failure'}]
const installationResults=[...results,{label:'服务检查失败',value:'health-failure'}]
const environmentDefinitions=[
 {key:'runtime',label:'运行环境',icon:'i-lucide-server',hint:'Linux 与 Node.js 24',failure:'请核对操作系统、架构与 Node.js 版本。'},
 {key:'paths',label:'安装目录',icon:'i-lucide-folder',hint:'目录权限与首次安装条件',failure:'请检查目录写入权限及是否存在已有安装数据。'},
 {key:'archive',label:'安装文件',icon:'i-lucide-file-archive',hint:'安装包与发行校验材料一致',failure:'请核对安装包路径、版本及发行校验材料。'},
 {key:'space',label:'磁盘空间',icon:'i-lucide-database',hint:'安装包展开所需空间',failure:'可用空间不足，请清理磁盘或扩容后重试。'},
 {key:'redis',label:'Redis 连接',icon:'i-lucide-layers',hint:'缓存服务可连接',failure:'请核对缓存主机、端口、密码及 TLS 设置。'},
]
const environmentRows=computed(()=>{
 const checks=preview?environmentDefinitions.map(item=>({...item,passed:environment.value==='idle'?null:!(environment.value==='failed'&&item.key==='redis')})):environmentChecks.value.length?environmentChecks.value:environmentDefinitions.map(item=>({...item,passed:null}))
 return checks.map(check=>{const definition=environmentDefinitions.find(item=>item.key===check.key),state=checkingEnvironment.value?'checking':check.passed===null?'idle':check.passed?'passed':'failed';return {...check,...definition,state,description:state==='failed'?('message' in check&&check.message||definition?.failure):definition?.hint}})
})
const environmentSummary=computed(()=>checkingEnvironment.value?'正在检查运行条件与 Redis 连接…':environment.value==='passed'?'全部检查通过，可以继续安装。':environment.value==='failed'?'请处理未通过的项目，然后重新检测。':'填写连接信息后，检测安装所需的运行条件。')
watch([step,authenticated,authorizationAllowed,locked,pageMounted],()=>{
 if(step.value!==1||!authenticated.value||!authorizationAllowed.value||locked.value||!pageMounted.value||environmentAutoStarted.value)return
 environmentAutoStarted.value=true
 if(environment.value==='idle')void wizard.inspectEnvironment()
},{flush:'post'})
const databaseFields=[{key:'host',label:'数据库主机',placeholder:'例如：127.0.0.1'},{key:'port',label:'端口',placeholder:'3306'},{key:'database',label:'数据库名称',placeholder:'例如：qicore'}] as const
watch(step,value=>{for(const key of Object.keys(passwordVisible) as (keyof typeof passwordVisible)[])passwordVisible[key]=false;if(installStep(route.query.step)!==value)void router.replace({path:'/install',query:{...(preview?{preview:'1'}:{}),step:String(value+1)}})})
watch(()=>route.query.step,value=>{if(!locked.value&&installStep(value)!==step.value)wizard.showStep(installStep(value))})
onBeforeUnmount(wizard.dispose)
function enterInstallation(){
 if(!live){void wizard.checkAuthorization();return}
 const token=new URLSearchParams(window.location.hash.slice(1)).get('setup')
 if(token)window.history.replaceState(window.history.state,'',window.location.pathname+window.location.search)
 void live.resume(token??undefined)
}
onMounted(()=>{if(live)window.addEventListener('hashchange',enterInstallation);enterInstallation();pageMounted.value=true})
onBeforeUnmount(()=>{if(live)window.removeEventListener('hashchange',enterInstallation)})
onBeforeRouteUpdate(to=>{if((locked.value||recoveryRequired.value)&&installStep(to.query.step)!==step.value)return false})
function previous(){wizard.showStep(step.value-1)}
</script>

<template>
 <main class="install-page">
  <header class="install-topbar"><a :href="preview?'/install?preview=1':'/install'" class="install-brand"><img src="/brand/qicore.png" alt="QiCore Logo"/><strong>QiCore</strong><span>启承框架</span></a><span class="topbar-caption">安装向导</span></header>
  <section class="install-shell" :class="{'environment-step':step===1}">
   <aside class="install-sidebar"><div class="sidebar-heading">安装流程<span>SETUP</span></div>
    <nav aria-label="安装步骤"><ol class="install-steps"><li v-for="(item,index) in installSteps" :key="item.title" :class="{active:step===index,visited:step>index}"><button type="button" :aria-current="step===index?'step':undefined" :aria-label="`第${index+1}步：${item.title}`" :disabled="locked||recoveryRequired" @click="wizard.showStep(index)"><span class="step-circle"><UIcon v-if="step>index" name="i-lucide-check"/><span v-else>{{index+1}}</span></span><span class="step-copy"><strong>{{item.title}}</strong><small>{{item.caption}}</small></span></button></li></ol></nav>
    <div class="sidebar-footer"><UIcon name="i-lucide-shield-check"/><span>独立部署<br/><small>为你的应用打好基础</small></span></div>
   </aside>
   <div class="install-body">
    <header class="install-header"><div><span class="install-kicker">步骤 0{{step+1}} / 06</span><h2>{{step===0?'免责声明与安装须知':current.title}}</h2></div><details v-if="preview" class="preview-menu"><summary class="preview-badge"><UIcon name="i-lucide-flask-conical"/>开发预览<UIcon name="i-lucide-chevron-down"/></summary><div class="preview-menu-content"><label>授权状态</label><USelect :model-value="authorizationScenario" :items="authorizationOptions" aria-label="授权预览状态" :disabled="locked" @update:model-value="wizard.changeAuthorization"/></div></details></header>
    <div v-if="preview" class="preview-notice"><UIcon name="i-lucide-info"/><span>点击步骤查看页面。安装操作仅演示，勾选不代表接受条款，请勿输入真实密码。</span></div>
    <section v-if="step<5" class="authorization-panel" aria-label="安装授权检查" :class="{allowed:authorizationAllowed,blocked:authorization.state!=='unchecked'&&!authorizationAllowed}">
     <div class="authorization-summary"><span class="authorization-icon"><UIcon :name="authorizationAllowed?'i-lucide-shield-check':'i-lucide-shield-question'"/></span><div><strong>{{checkingAuthorization?'正在检测安装授权…':authorizationView.title}}</strong><p>{{authorization.domain||'当前访问域名'}}<span> · {{preview?(authorizationScenario==='live'?'本机已签名回执':'授权状态演示'):'在线授权与签名回执'}}</span></p></div></div>
     <div class="authorization-actions"><span class="authorization-badge">{{checkingAuthorization?'检测中':authorizationView.badge}}</span><UButton type="button" color="neutral" variant="outline" :disabled="locked" @click="wizard.checkAuthorization"><UIcon name="i-lucide-refresh-cw" :class="{'animate-spin':checkingAuthorization}"/>重新检测</UButton></div>
     <p v-if="authorization.state!=='unchecked'&&!authorizationAllowed" class="authorization-hint">{{authorizationView.hint}}</p>
    </section>
    <form class="install-form" autocomplete="off" @submit.prevent="wizard.next">
     <div class="install-scroll">
      <section v-if="!authenticated" class="install-access" role="status"><UIcon name="i-lucide-lock-keyhole"/><div><strong>{{accessBusy?'正在进入安装…':accessError||'请使用专属安装链接继续'}}</strong><p>在宝塔的 Node 项目日志中找到安装链接，打开后即可继续。</p></div><UButton type="button" color="neutral" variant="outline" @click="installHelpOpen=true">查看获取方式</UButton></section>
      <UAlert v-if="notice" color="neutral" variant="soft" :title="notice" class="mb-5" role="status"/>
      <UAlert v-if="!preview&&step!==4&&installationError" color="error" variant="soft" title="上次安装未完成" :description="installationError" class="mb-5"/>

      <article v-if="step===0" class="install-notice" aria-label="软件许可与合规使用声明">
       <header><h3>QiCore 软件许可与合规使用声明</h3><p>请在正式安装、部署或使用本软件前，完整阅读并理解以下条款。</p></header>
       <section><h4>一、合法用途与禁止行为</h4><p>部署者必须遵守业务实际运营地适用的法律法规，不得利用 QiCore 直接或间接实施、协助、宣传、引流，或为下列活动提供技术便利：</p><ul><li>诈骗、赌博、色情、毒品、违禁品、非法集资、传销、洗钱、非法支付结算及其他违法犯罪活动；</li><li>未经授权侵入、控制或破坏计算机系统，传播恶意程序，窃取账号凭证，发动拒绝服务攻击或提供黑灰产工具；</li><li>非法收集、买卖、泄露或滥用个人信息，侵犯隐私、商业秘密、著作权、商标权及其他合法权益；</li><li>制作、发布或传播法律法规禁止的信息，冒用他人身份、资质或品牌实施误导性经营；</li><li>规避监管、审计、实名认证、内容治理或安全控制，以及其他危害网络与数据安全的行为。</li></ul></section>
       <section><h4>二、运营主体与合规责任</h4><p>部署者是所搭建站点、应用、接口、内容、交易和数据处理活动的实际运营主体，应自行取得所需许可、备案、授权与资质，并依法制定隐私政策、用户协议、内容审核和投诉处理机制。</p><p>梦承网络科技提供通用软件技术，不参与、不控制、不授权也不背书部署者的具体业务。因部署者业务、内容、用户行为或二次开发产生的法律责任，由实际运营者及相关责任人依法承担。</p></section>
       <section><h4>三、数据、安全与部署义务</h4><ul><li>安装前应备份服务器、数据库与配置文件，并先在隔离环境完成兼容性和恢复测试；</li><li>妥善保护管理员账号、数据库凭据、密钥和日志，及时安装安全更新并限制管理入口访问；</li><li>处理个人信息时，遵循合法、正当、必要和最小化原则，并落实访问控制、留存和删除机制；</li><li>不得移除、规避或破坏软件内置的安全、授权、审计以及租户与应用数据隔离机制。</li></ul></section>
       <section><h4>四、软件许可与第三方组件</h4><p>部署者仅可在所获得的软件授权范围内使用、修改和交付 QiCore。第三方组件分别适用其自身许可证；部署者应核验二次开发、分发及商用行为是否满足相应条款。</p></section>
       <section><h4>五、风险承担与责任限制</h4><p>软件按现状提供。部署者应对环境配置、二次开发、数据备份、业务连续性和安全运营负责。因错误配置、未及时更新、第三方服务、违规经营或超出授权范围使用导致的损失，在适用法律允许的范围内由部署者自行承担。依法不得排除或限制的责任不受本声明影响。</p></section>
       <section><h4>六、违规处置</h4><p>如发现软件被用于违法违规活动，梦承网络科技有权在法律及授权协议允许的范围内终止授权、更新与技术支持，并依法保存必要证据、配合有权机关调查。该等处置不免除实际违法者应承担的责任。</p></section>
       <section><h4>七、本次安装确认</h4><p>正式安装前，部署者应确认已获得服务器与数据库的操作授权，并了解数据库初始化、管理员创建及运行配置写入的影响。安装失败或中断时，应保留已有进度和恢复记录，核查原因后再继续。</p><p>若不同意本声明，或无法确认部署权限与业务合法性，请停止正式安装和使用。<template v-if="preview">当前页面仅供开发预览，不执行真实安装，也不记录条款接受状态。</template></p></section>
      </article>

      <template v-else-if="step===1">
       <section v-if="redis&&authenticated" class="redis-section"><header class="redis-connection-summary"><span class="redis-summary-icon"><UIcon name="i-lucide-layers"/></span><div><h3>Redis 连接<small>默认配置通常无需修改，检测通过后可直接继续。</small></h3><p>{{redis.host}}:{{redis.port}}<span>数据库 {{redis.database}}</span><span>{{redis.tls?'TLS 已开启':'TLS 未开启'}}</span></p></div><UButton type="button" color="neutral" variant="outline" :aria-expanded="redisExpanded" aria-controls="redis-connection-settings" @click="redisExpanded=!redisExpanded">{{redisExpanded?'收起配置':'修改配置'}}<UIcon :name="redisExpanded?'i-lucide-chevron-up':'i-lucide-chevron-down'"/></UButton></header><div v-show="redisExpanded" id="redis-connection-settings" class="redis-connection-settings"><p class="redis-settings-note">{{preview?"当前为连接配置示例，不连接真实 Redis。":"已读取部署配置。使用其他 Redis 服务时，可在这里修改连接信息。"}}</p><div class="redis-fields">
        <UFormField label="缓存主机" name="redisHost" class="redis-host" required><ConsoleInput v-model="redis.host" :disabled="installing" placeholder="127.0.0.1"/></UFormField>
        <UFormField label="端口" name="redisPort" required><ConsoleInput v-model="redis.port" type="number" :min="1" :max="65535" :disabled="installing"/></UFormField>
        <UFormField label="数据库编号" name="redisDatabase" required><ConsoleInput v-model="redis.database" type="number" :min="0" :max="255" :disabled="installing"/></UFormField>
        <UFormField label="用户名" name="redisUsername" class="redis-credential"><ConsoleInput v-model="redis.username" autocomplete="off" :disabled="installing" placeholder="选填，未设置时留空"/></UFormField>
        <UFormField label="密码" name="redisPassword" class="redis-credential"><ConsoleInput v-model="redis.password" :type="passwordVisible.redis?'text':'password'" autocomplete="new-password" :disabled="installing||redis.keepPassword" :placeholder="redis.keepPassword?'使用已保存密码':'选填，未设置时留空'"><template #trailing><UButton type="button" color="neutral" variant="link" :icon="passwordVisible.redis?'i-lucide-eye-off':'i-lucide-eye'" :aria-label="passwordVisible.redis?'隐藏Redis 密码':'显示Redis 密码'" :aria-pressed="passwordVisible.redis" :disabled="installing||redis.keepPassword" @click="passwordVisible.redis=!passwordVisible.redis"/></template></ConsoleInput></UFormField>
       </div><UCheckbox v-if="redis.hasPassword" v-model="redis.keepPassword" class="redis-password-setting" label="保留已保存密码" :disabled="installing"/><div class="redis-tls"><div><label for="install-redis-tls">TLS 加密连接</label><p>仅在 Redis 服务启用 TLS 时开启，与网站 HTTPS 无关。</p></div><USwitch id="install-redis-tls" v-model="redis.tls" aria-label="TLS 加密连接" :disabled="installing"/></div></div></section>
       <section class="environment-checks" aria-label="环境检测"><header class="environment-heading"><div><h3>环境检测</h3><p role="status" aria-live="polite">{{environmentSummary}}</p></div><div class="environment-tools"><USelect v-if="preview" v-model="environmentResult" :items="results" aria-label="环境检查演示结果" :disabled="locked"/><UButton type="button" :disabled="locked||!authenticated" :loading="checkingEnvironment" @click="wizard.inspectEnvironment">{{checkingEnvironment?'正在检测':environment==='idle'?'检测环境':'重新检测'}}</UButton></div></header>
        <p v-if="!preview&&environment==='failed'&&!environmentChecks.some(check=>!check.passed)" class="environment-request-error" role="alert">{{environmentError}}</p>
        <div class="environment-results"><div v-for="check in environmentRows" :key="check.key" class="environment-check" :class="check.state"><span class="environment-check-icon"><UIcon :name="check.icon||'i-lucide-circle-help'"/></span><div><strong>{{check.label}}</strong><p>{{check.description}}</p></div><span class="environment-check-state"><UIcon :name="check.state==='passed'?'i-lucide-circle-check':check.state==='failed'?'i-lucide-circle-alert':check.state==='checking'?'i-lucide-loader-circle':'i-lucide-circle'" :class="{'animate-spin':check.state==='checking'}"/>{{check.state==='checking'?'检测中':check.state==='passed'?'通过':check.state==='failed'?'未通过':'待检测'}}</span></div></div>
       </section>
      </template>

      <template v-else-if="step===2">
       <div class="section-tools"><span>MySQL 8.0 数据库</span></div>
       <section class="form-section"><div class="install-fields database-fields"><UFormField v-for="field in databaseFields" :key="field.key" :label="field.label" :name="field.key" :error="errors[field.key]" required :class="{'full-field':field.key==='database'}"><ConsoleInput v-model="form[field.key]" :type="field.key==='port'?'number':'text'" :placeholder="field.placeholder" :disabled="installing" :min="field.key==='port'?1:undefined" :max="field.key==='port'?65535:undefined"/></UFormField></div>
        <div class="install-fields database-credentials"><UFormField label="数据库用户名" name="databaseUsername" :error="errors.databaseUsername" required><ConsoleInput v-model="form.databaseUsername" placeholder="请输入数据库用户名" :maxlength="100" autocomplete="off" :disabled="installing"/></UFormField><UFormField label="数据库密码" name="databasePassword" :error="errors.databasePassword" required><ConsoleInput v-model="form.databasePassword" :type="passwordVisible.database?'text':'password'" :maxlength="256" autocomplete="new-password" placeholder="请输入数据库密码" :disabled="installing"><template #trailing><UButton type="button" color="neutral" variant="link" :icon="passwordVisible.database?'i-lucide-eye-off':'i-lucide-eye'" :aria-label="passwordVisible.database?'隐藏数据库密码':'显示数据库密码'" :aria-pressed="passwordVisible.database" :disabled="installing" @click="passwordVisible.database=!passwordVisible.database"/></template></ConsoleInput></UFormField></div>
        <p class="database-note"><UIcon name="i-lucide-info"/><span>请使用独立数据库，已有业务数据不会被覆盖。<small v-if="preview">当前为流程预览，不会连接或修改数据库。</small></span></p>
       </section>
       <div class="connection-tools"><USelect v-if="preview" v-model="connectionResult" :items="results" aria-label="连接检查演示结果" :disabled="locked"/><UButton class="connection-check" type="button" color="neutral" variant="outline" :disabled="locked" @click="wizard.testConnections"><UIcon name="i-lucide-refresh-cw" :class="{'animate-spin':checkingConnections}"/>{{checkingConnections?'检查连接中':'测试连接'}}</UButton><span v-if="connections==='passed'" class="connection-passed" role="status"><UIcon name="i-lucide-circle-check"/>{{preview?'连接检查通过（演示）':'连接检查通过'}}</span></div>
       <UAlert v-if="connections==='failed'" color="error" variant="soft" :title="preview?'连接检查未通过（演示）':'数据库连接未通过'" :description="preview?'请核对主机、端口、账号及权限后重试。本次没有连接任何数据库。':connectionError" class="mt-4"/>
      </template>

      <template v-else-if="step===3">
       <div class="admin-intro"><span><UIcon name="i-lucide-shield-check"/></span><div><h4>创建平台管理员</h4><p>用于管理租户、公共能力与系统设置。</p></div><UBadge color="primary" variant="soft">平台管理员</UBadge></div>
       <div class="install-fields admin-fields"><UFormField label="管理员账号" name="username" :error="errors.username" required><ConsoleInput v-model="form.username" :maxlength="32" autocomplete="off" placeholder="例如：admin"/></UFormField><UFormField label="显示名称" name="nickname" :error="errors.nickname" required><ConsoleInput v-model="form.nickname" :maxlength="40" placeholder="例如：总管理员"/></UFormField><UFormField label="登录密码" name="password" :error="errors.password" required><ConsoleInput v-model="form.password" :type="passwordVisible.administrator?'text':'password'" :maxlength="128" autocomplete="new-password" placeholder="请输入登录密码"><template #trailing><UButton type="button" color="neutral" variant="link" :icon="passwordVisible.administrator?'i-lucide-eye-off':'i-lucide-eye'" :aria-label="passwordVisible.administrator?'隐藏登录密码':'显示登录密码'" :aria-pressed="passwordVisible.administrator" :disabled="installing" @click="passwordVisible.administrator=!passwordVisible.administrator"/></template></ConsoleInput></UFormField><UFormField label="确认密码" name="confirmPassword" :error="errors.confirmPassword" required><ConsoleInput v-model="form.confirmPassword" :type="passwordVisible.confirmation?'text':'password'" :maxlength="128" autocomplete="new-password" placeholder="请再次输入密码"><template #trailing><UButton type="button" color="neutral" variant="link" :icon="passwordVisible.confirmation?'i-lucide-eye-off':'i-lucide-eye'" :aria-label="passwordVisible.confirmation?'隐藏确认密码':'显示确认密码'" :aria-pressed="passwordVisible.confirmation" :disabled="installing" @click="passwordVisible.confirmation=!passwordVisible.confirmation"/></template></ConsoleInput></UFormField></div>
      </template>

      <template v-else-if="step===4">
       <dl class="install-summary"><div><dt>框架名称</dt><dd>QiCore <small>启承框架</small></dd></div><div><dt>数据库</dt><dd>{{form.database||'未填写'}}<small>{{form.host}}:{{form.port}}</small></dd></div><div><dt>平台管理员</dt><dd>{{form.username||'未填写'}}</dd></div><div><dt>安装方式</dt><dd>独立部署</dd></div></dl>
