      </template>

      <div v-else class="install-complete"><span class="complete-icon"><UIcon name="i-lucide-circle-check"/></span><span class="complete-kicker">READY TO BUILD</span><h4>一切就绪，开始构建</h4><p v-if="preview">这是安装完成页面的预览。<br/>本次没有创建数据库、管理员或安装回执。</p><p v-else>系统已完成初始化与服务检查。<br/>可以使用刚设置的管理员账号进入后台。</p><div class="complete-items"><span><UIcon name="i-lucide-check"/> 数据服务</span><span><UIcon name="i-lucide-check"/> 平台管理员</span><span><UIcon name="i-lucide-check"/> 系统配置</span></div><div class="next-card"><UIcon name="i-lucide-layout-dashboard"/><div><strong>下一步，配置你的平台</strong><p>设置站点品牌，安装所需应用后再创建租户。</p></div></div></div>
     </div>
     <footer class="install-actions">
      <label v-if="step===0" class="notice-consent"><input v-model="accepted" type="checkbox"/>我已阅读并同意以上声明与安装须知</label><span v-else class="action-hint"><UIcon name="i-lucide-shield-check"/>{{preview?'开发预览':'独立安装'}}</span>
      <ConsoleFormActions>
       <UButton v-if="step>0&&step<5" type="button" color="neutral" variant="outline" :disabled="locked||recoveryRequired" @click="previous">上一步</UButton>
       <UButton v-if="step<4" type="submit" :disabled="locked||!authenticated||!authorizationAllowed||(step===0&&!accepted)||(step===1&&environment!=='passed')">下一步<UIcon name="i-lucide-chevron-right"/></UButton>
       <UButton v-if="preview&&step===4&&installing" type="button" color="neutral" variant="outline" @click="wizard.cancelInstallation">停止演示</UButton>
       <UButton v-if="step===4&&(canResume||resuming)" type="button" :loading="resuming" :disabled="locked||!authenticated" @click="wizard.retryInstallation()">{{resuming?'正在继续安装':'重试并继续安装'}}</UButton>
       <UButton v-else-if="step===4&&!recoveryRequired" type="button" :loading="installing" :disabled="locked||!authorizationAllowed" @click="wizard.simulateInstallation">{{preview?(installing?'正在演示安装':installationError?'重新演示安装':'演示安装过程'):(installing?'正在安装':'开始安装')}}</UButton>
       <UButton v-if="preview&&step===5" type="button" color="neutral" variant="outline" @click="wizard.showStep(0)">重新查看</UButton>
       <UButton v-if="step===5" href="/admin/login" external>{{preview?'进入现有后台':'进入后台'}}<UIcon name="i-lucide-chevron-right"/></UButton>
      </ConsoleFormActions>
     </footer>
    </form>
   </div>
  </section>
  <footer class="install-page-footer"><span>QiCore · 启承服务</span><button type="button" class="install-help-trigger" @click="installHelpOpen=true"><UIcon name="i-lucide-circle-help"/>找不到安装链接？</button></footer>
